/**
 * What SiteScene draws, derived from the plan contract and the grid. No
 * invented values: every constant names its source.
 */
import { formatPercent } from "@/lib/format";
import { lonLatToGrid } from "@/lib/grid";
import { diffPlans, orderedStations, type Plan, type Station } from "@/lib/plan";
import imagery from "@/public/site/s1094b.json";

import type { Box } from "./camera";

/** Generated by apps/web/scripts/build-site-imagery.py. */
export const SITE_IMAGERY = {
  credit: imagery.credit,
  overview: {
    src: imagery.images.overview.file,
    box: imagery.images.overview.box_m as Box,
    width: imagery.images.overview.width_px,
    height: imagery.images.overview.height_px,
  },
  detail: {
    src: imagery.images.detail.file,
    box: imagery.images.detail.box_m as Box,
    width: imagery.images.detail.width_px,
    height: imagery.images.detail.height_px,
  },
} as const;

/** The camera never leaves the overview image. */
export const SCENE_BOUNDS: Box = SITE_IMAGERY.overview.box;

/**
 * Habitat in grid meters. apps/planner/config/eva.yaml `habitat_xy` (assumption: true,
 * decision of 2026-11-08). Not in the plan contract yet; read it from the STM when it is.
 */
export const HABITAT_XY: [number, number] = [300, -2200];

/**
 * Spatial range of the fitted GP prior: half spatial with a 100 m range, half
 * nugget (docs/plans/planner.md, "Interfaz del GP", make_prior(**FITTED)).
 * Read it from the backend once it is exposed.
 */
export const MODEL_RANGE_M = 100;

/** contracts/grid.json station_grid_cell_size_m. Stations sit at the cell centers. */
export const STATION_CELL_M = 100;

/** The 2021 impact is the grid origin (contracts/grid.json crs.origin). */
export const CRATER_XY: [number, number] = [0, 0];
export const CRATER_LABEL = "S1094b impact · 2021";

export type RouteLine = [number, number][];

/** LineStrings of plan.route (GeoJSON, east lon/lat) in grid meters, as they come. */
export function routeLines(plan: Plan): RouteLine[] {
  const lines: RouteLine[] = [];
  for (const feature of plan.route.features as { geometry?: { type?: string; coordinates?: unknown } }[]) {
    const g = feature.geometry;
    if (g?.type === "LineString") {
      lines.push((g.coordinates as [number, number][]).map((c) => lonLatToGrid(c)));
    } else if (g?.type === "MultiLineString") {
      for (const part of g.coordinates as [number, number][][]) lines.push(part.map((c) => lonLatToGrid(c)));
    }
  }
  return lines;
}

export function pIceLabel(station: Pick<Station, "p_ice">): string {
  return formatPercent(station.p_ice);
}

/** Accessible name: "Station 1, E03S22, P(ice) 65%". */
export function stationName(station: Station): string {
  return `Station ${station.order}, ${station.id}, P(ice) ${pIceLabel(station)}`;
}

export type SceneStation = Station & { status: "planned" | "added" };
export type DroppedStation = Station & { status: "dropped" };

/** Current stations with their re-plan status, and the ones the re-plan dropped. */
export function sceneStations(plan: Plan, previous?: Plan) {
  const diff = previous ? diffPlans(previous, plan) : undefined;
  const added = new Set(diff?.added.map((s) => s.id));
  const stations: SceneStation[] = orderedStations(plan).map((s) => ({
    ...s,
    status: added.has(s.id) ? "added" : "planned",
  }));
  const dropped: DroppedStation[] = (diff?.removed ?? []).map((s) => ({ ...s, status: "dropped" }));
  return { stations, dropped };
}

/** Points to frame: the stations and the habitat. */
export function framePoints(plan: Plan, ids?: readonly string[]): [number, number][] {
  const chosen = ids?.length ? plan.stations.filter((s) => ids.includes(s.id)) : plan.stations;
  const points = chosen.map((s) => [s.position[0], s.position[1]] as [number, number]);
  return ids?.length ? points : [...points, HABITAT_XY];
}

/** Whether the habitat sits on a station, so its mark is offset with a leader line. */
export function habitatOnStation(stations: readonly Station[]): boolean {
  return stations.some((s) => Math.hypot(s.position[0] - HABITAT_XY[0], s.position[1] - HABITAT_XY[1]) < 1);
}
